# History is append-only (NFR-05): the database rejects changes to it, so no code
# path can rewrite history by accident.
APPEND_ONLY_TABLES = (
    "thesis_revision",
    "portfolio_assignment",
    "snapshot",
    "snapshot_value",
    "rebalance",
    "rebalance_action",
    "review_source",
    "review_suggestion",
    "review_portfolio_score",
    "timeline_event",
)


def _create_history_triggers() -> None:
    for table in APPEND_ONLY_TABLES:
        for action in ("UPDATE", "DELETE"):
            op.execute(
                f"CREATE TRIGGER {table}_no_{action.lower()} BEFORE {action} ON {table} "
                f"BEGIN SELECT RAISE(ABORT, '{table} is append-only'); END"
            )
    # Activated policy versions and their positions are immutable; drafts are not.
    for action in ("UPDATE", "DELETE"):
        op.execute(
            f"CREATE TRIGGER policy_version_activated_no_{action.lower()} "
            f"BEFORE {action} ON policy_version WHEN OLD.activated_at IS NOT NULL "
            "BEGIN SELECT RAISE(ABORT, 'activated policy version is immutable'); END"
        )
    for action, row in (("INSERT", "NEW"), ("UPDATE", "OLD"), ("DELETE", "OLD")):
        op.execute(
            f"CREATE TRIGGER policy_position_activated_no_{action.lower()} "
            f"BEFORE {action} ON policy_position WHEN (SELECT activated_at FROM policy_version "
            f"WHERE id = {row}.policy_version_id) IS NOT NULL "
            "BEGIN SELECT RAISE(ABORT, 'activated policy version is immutable'); END"
        )
    # A finished review is history; queued/running reviews still change state.
    for action in ("UPDATE", "DELETE"):
        op.execute(
            f"CREATE TRIGGER thesis_review_finished_no_{action.lower()} "
            f"BEFORE {action} ON thesis_review WHEN OLD.state IN ('done', 'failed') "
            "BEGIN SELECT RAISE(ABORT, 'finished thesis review is immutable'); END"
        )


